    $_POST['book_type']='used';$_POST['stock_quantity']=1;
    $result=handleSaveBook($pdo,$userId,'user',$sellerName,isset($_POST['draft'])?'draft':'available');
    $success=$result['success']??'';$error=$result['error']??'';
}
