<section class="panel"><h2>4. วิธีจัดส่ง</h2><div class="shipping"><label><input type="checkbox" name="shipping[]" value="standard" checked> บริษัทขนส่ง</label><label><input type="checkbox" name="shipping[]" value="thailand_post"> ไปรษณีย์ไทย</label><label><input type="checkbox" name="shipping[]" value="pickup"> นัดรับ</label></div></section><div class="actions"><button class="btn publish" type="submit" name="publish">ลงขายหนังสือ</button><button class="btn draft" type="submit" name="draft">บันทึกร่าง</button></div></form></main><?php require __DIR__.'/../components/footer.php';?><script>const previewUrls={};function showBookPreview(input,key){const file=input.files&&input.files[0];const slot=document.getElementById('slot-'+key);const preview=document.getElementById('preview-'+key);if(previewUrls[key])URL.revokeObjectURL(previewUrls[key]);if(!file){preview.removeAttribute('src');slot.classList.remove('has-preview');return}previewUrls[key]=URL.createObjectURL(file);preview.src=previewUrls[key];slot.classList.add('has-preview')}</script></body></html>
